(function() {
    tinymce.PluginManager.add('checklist', function(editor, url) {

        var COLOR_CLASSES = ['list-primary', 'list-secondary', 'list-success', 'list-alert', 'list-dark', 'list-gray', 'list-blue', 'list-green', 'list-red', 'list-yellow'];

        function getClasses(dom, node) {
            var raw = (dom.getAttrib(node, 'class') || '').trim();
            return raw ? raw.split(/\s+/).filter(Boolean) : [];
        }

        function setClasses(dom, node, classList) {
            var unique = [];
            classList.filter(Boolean).forEach(function(c) {
                c = c.trim();
                if (c && unique.indexOf(c) === -1) {
                    unique.push(c);
                }
            });
            dom.setAttrib(node, 'class', unique.length ? unique.join(' ') : null);
        }

        function applyListStyle(styleClass) {
            editor.undoManager.transact(function() {
                var dom = editor.dom;
                var currentList = dom.getParent(editor.selection.getStart(), 'ul,ol');

                if (styleClass === 'remove') {
                    if (currentList) {
                        var classes = getClasses(dom, currentList).filter(function(c) {
                            return !c.startsWith('list-');
                        });
                        setClasses(dom, currentList, classes);
                    }
                    editor.nodeChanged();
                    return;
                }

                if (currentList) {
                    if (currentList.nodeName === 'OL') {
                        currentList = dom.rename(currentList, 'ul');
                    }

                    var classes = getClasses(dom, currentList).filter(function(c) {
                        return COLOR_CLASSES.indexOf(c) !== -1 || !c.startsWith('list-');
                    });
                    classes.push(styleClass);
                    setClasses(dom, currentList, classes);

                    editor.nodeChanged();
                    return;
                }

                var selectedBlocks = editor.selection.getSelectedBlocks();
                var selContent = editor.selection.getContent({ format: 'html' });

                if (!selContent || selContent.trim() === '') {
                    var html = '<ul class="' + styleClass + '"><li>&nbsp;</li></ul>';
                    editor.insertContent(html);
                } else if (selectedBlocks && selectedBlocks.length > 0) {
                    var listItems = [];
                    selectedBlocks.forEach(function(block) {
                        var html = block.innerHTML.trim();
                        if (html !== '') {
                            listItems.push('<li>' + html + '</li>');
                        }
                    });

                    if (listItems.length > 0) {
                        var newUl = '<ul class="' + styleClass + '">' + listItems.join('') + '</ul>';
                        dom.replace(dom.createFragment(newUl), selectedBlocks[0]);
                        for (var i = 1; i < selectedBlocks.length; i++) {
                            dom.remove(selectedBlocks[i]);
                        }
                    }
                }

                editor.nodeChanged();
            });
        }

        function applyListColor(colorClass) {
            editor.undoManager.transact(function() {
                var dom = editor.dom;
                var currentList = dom.getParent(editor.selection.getStart(), 'ul,ol');

                if (!currentList) {
                    return;
                }

                var classes = getClasses(dom, currentList).filter(function(c) {
                    return COLOR_CLASSES.indexOf(c) === -1;
                });

                if (colorClass) {
                    classes.push(colorClass);
                }

                setClasses(dom, currentList, classes);
                editor.nodeChanged();
            });
        }

        editor.addButton('checklist', {
            type: 'menubutton',
            title: 'List Styles',
            icon: 'checklist is-dashicon dashicons dashicons-yes-alt',
            menu: [
                {
                    text: '➔  Arrow (.list-arrow)',
                    onclick: function() { applyListStyle('list-arrow'); }
                },
                {
                    text: '❯  Chevron (.list-chevron)',
                    onclick: function() { applyListStyle('list-chevron'); }
                },
                {
                    text: '✔  Check (.list-check)',
                    onclick: function() { applyListStyle('list-check'); }
                },
                {
                    text: '☑  Circle Check (.list-circle-check)',
                    onclick: function() { applyListStyle('list-circle-check'); }
                },
                {
                    text: '☐  Square (.list-square)',
                    onclick: function() { applyListStyle('list-square'); }
                },
                {
                    text: '☑  Square Check (.list-square-check)',
                    onclick: function() { applyListStyle('list-square-check'); }
                },
                {
                    text: '✖  Cross (.list-cross)',
                    onclick: function() { applyListStyle('list-cross'); }
                },
                {
                    text: '☒  Circle Cross (.list-circle-cross)',
                    onclick: function() { applyListStyle('list-circle-cross'); }
                },
                {
                    text: '⭐  Star (.list-star)',
                    onclick: function() { applyListStyle('list-star'); }
                },
                {
                    text: '●  Dot (.list-dot)',
                    onclick: function() { applyListStyle('list-dot'); }
                },
                {
                    text: '✚  Plus (.list-plus)',
                    onclick: function() { applyListStyle('list-plus'); }
                },
                {
                    text: '➖  Minus (.list-minus)',
                    onclick: function() { applyListStyle('list-minus'); }
                },
                { text: '-' },
                {
                    text: '🎨  Icon Color',
                    menu: [
                        { text: '🎯  Flatsome Primary (.list-primary)', onclick: function() { applyListColor('list-primary'); } },
                        { text: '🔶  Flatsome Secondary (.list-secondary)', onclick: function() { applyListColor('list-secondary'); } },
                        { text: '🟢  Flatsome Success (.list-success)', onclick: function() { applyListColor('list-success'); } },
                        { text: '🔴  Flatsome Alert (.list-alert)', onclick: function() { applyListColor('list-alert'); } },
                        { text: '⚫  Flatsome Dark (.list-dark)', onclick: function() { applyListColor('list-dark'); } },
                        { text: '⚪  Flatsome Gray (.list-gray)', onclick: function() { applyListColor('list-gray'); } },
                        { text: '-' },
                        { text: '🔵  Blue (.list-blue)', onclick: function() { applyListColor('list-blue'); } },
                        { text: '🟢  Green (.list-green)', onclick: function() { applyListColor('list-green'); } },
                        { text: '🔴  Red (.list-red)', onclick: function() { applyListColor('list-red'); } },
                        { text: '🟡  Yellow (.list-yellow)', onclick: function() { applyListColor('list-yellow'); } },
                        { text: '-' },
                        { text: '🔄  Theme Default', onclick: function() { applyListColor(''); } }
                    ]
                },
                { text: '-' },
                {
                    text: '🚫  Default / Remove Style',
                    onclick: function() { applyListStyle('remove'); }
                }
            ],
            onPostRender: function() {
                if (window.jQuery) {
                    jQuery('.is-dashicon').css('font-family', 'dashicons');
                }
            }
        });

        editor.on('init', function() {
            var cssUrl = url.replace(/\/tinymce\/checklist\/?$/, '/css/checklist.min.css');
            if (editor.dom && editor.dom.loadCSS) {
                editor.dom.loadCSS(cssUrl);
            }
        });
    });
})();
